"""Read-only postprobe audit: coverage, rank margins, endpoint comparability."""
import datetime,json,sys,time
from pathlib import Path
from retry.loss389_analyze import read,save,sha

def run(root):
 d=root/'stage406';assert not(d/'analysis.json').exists();paths=[Path(__file__),d/'result.json',d/'candidate-forecasts-private.json',root/'stage404/C_268/trace-private.jsonl'];save(d/'analysis-plan.json',dict(at_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),scope='Posthocstoredforecasts only, selected13stependpoint vsactual404failurearc; rankmargin, goalfirsthit, applied2stepprogress;no new transitions/control reevaluation.',sources={str(f):sha(f) for f in paths},new_native_actor_model_learning_SEALED=0));start,cpu=time.perf_counter(),time.process_time();x=read(d/'result.json');ff=read(d/'candidate-forecasts-private.json');actual=[json.loads(s) for s in (root/'stage404/C_268/trace-private.jsonl').read_text().splitlines()];target=actual[-1]['post_projection']['arc'];out=[]
 for state in x['results']:
  for decision in state['decisions']:
   query=next(z for z in ff if z['state']==state['state'] and z['decision']==decision['decision']);fs=query['forecasts'];chosen=fs[str(decision['selected'])];eligible=[(i,f) for i,f in fs.items() if f['valid']];ranked=sorted(eligible,key=lambda z:(z[1]['score'],z[1]['max_path_error'],z[1]['max_abs_yaw'],int(z[0])));margin=ranked[1][1]['score']-ranked[0][1]['score'] if len(ranked)>1 else None;goal=decision['goal_before'];deadline=decision['deadline_before'];hits=[r['offset'] for r in chosen['rows'] if decision['decision']+r['offset']<=deadline and r['arc']>=goal];assert hits
   out.append(dict(state=state['state'],decision=decision['decision'],selected=decision['selected'],valid_slots=decision['valid_count'],valid_unique_sequences=decision['valid_unique_count'],score_margin_to_next_slot=margin,first_goal_hit_forecast_offset=hits[0],forecast_max_path_error=chosen['max_path_error'],forecast_max_yaw=chosen['max_abs_yaw'],forecast_max_rear_force_ratio=max(r['rear_max_force_ratio'] for r in chosen['rows']),forecast_max_rear_lateral_slip=max(r['rear_max_abs_lateral_slip'] for r in chosen['rows']),distance_short_of_original_C_failure_arc_m=target-chosen['rows'][-1]['arc'] if state['state']=='C268_pre91' else None,first_two_parent_progress_m=sum(z['actual_parent_model_progress'] for z in state['decisions']),deadline_before=deadline,deadline_after_parent=decision['deadline_after'],retained_slot_valid=decision['retained_slot_valid']))
 cref=next(q for q in ff if q['state']=='C268_pre91' and q['decision']==0)['forecasts'];safe={k:f for k,f in cref.items() if f['valid']};assert set(safe)=={'1','3','5'};cfirst=cref['5'];second=next(q for q in ff if q['state']=='C268_pre91' and q['decision']==1)['forecasts']['0'];delta=[a-b for a,b in zip(cfirst['actions'][1],second['actions'][0])]
 result=dict(states=out,C_first_decision=dict(safe_slots=['1','3','5'],unsafe_slots=['0','2','4'],brake_family_only_safe_in_this_probe=True,safe_max_error_range=[min(z['max_path_error'] for z in safe.values()),max(z['max_path_error'] for z in safe.values())],chosen_plan_second_action_minus_replanned_nominal=delta,scope='Steerchoiceandpedalchangecombined,noactualcausalcomponentseparation'),same_arc_recovery_shown=False,next_actual_proposal_executed=False,new_native_actor_model_learning_SEALED=0,CPU_s=time.process_time()-cpu,wall_s=time.perf_counter()-start);save(d/'analysis.json',result);print(json.dumps(result,ensure_ascii=False))
if __name__=='__main__':run(Path(sys.argv[1]))
